import csv
import io
import itertools
import random
import unittest

from csvline import format_row, parse_row


def csv_line(fields, quoting=csv.QUOTE_MINIMAL):
    """Independent stdlib oracle, removing only the record terminator."""
    output = io.StringIO(newline="")
    csv.writer(output, quoting=quoting, lineterminator="\r\n").writerow(fields)
    return output.getvalue()[:-2]


def generated_rows():
    # Deliberately exercise empty fields and quote/comma boundaries in all positions.
    atoms = ["", "a", "b", ",", '"', '\",', ',\"', '\"\"', " a ", "\t", "é", "猫🙂"]
    for size in range(4):
        for fields in itertools.product(atoms, repeat=size):
            yield list(fields)

    # Exhaust quote escaping transitions within individual fields.
    for size in range(5):
        for chars in itertools.product('a,"', repeat=size):
            field = "".join(chars)
            yield [field]
            yield ["", field, "tail", ""]

    # Fixed seed makes broader, longer cases reproducible without dependencies.
    rng = random.Random(74193)
    alphabet = 'abcXYZ019 ,"\t\x00é猫🙂'
    for _ in range(600):
        yield [
            "".join(rng.choice(alphabet) for _ in range(rng.randrange(65)))
            for _ in range(rng.randrange(17))
        ]


class CsvRowTest(unittest.TestCase):
    def test_exact_boundary_examples(self):
        examples = [
            ([], ""),
            ([""], '""'),
            (["", ""], ","),
            (["", "a", ""], ",a,"),
            (["a", "b"], "a,b"),
            (["a,b", "c"], '"a,b",c'),
            (['"'], '""""'),
            (['a"b'], '"a""b"'),
            ([",", '"', ""], '\",\",\"\"\"\",'),
            ([" a ", "\t", "猫🙂"], " a ,\t,猫🙂"),
        ]
        for fields, line in examples:
            with self.subTest(fields=fields, line=line):
                self.assertEqual(format_row(fields), line)
                self.assertEqual(parse_row(line), fields)

    def test_formatter_matches_independent_csv_writer(self):
        for fields in generated_rows():
            with self.subTest(fields=fields):
                self.assertEqual(format_row(fields), csv_line(fields))

    def test_parser_reads_independently_encoded_rows(self):
        for fields in generated_rows():
            # Fully quoted rows also check valid input the formatter never emits,
            # such as quoted ordinary text and quoted empty trailing fields.
            for quoting in (csv.QUOTE_MINIMAL, csv.QUOTE_ALL):
                line = csv_line(fields, quoting)
                with self.subTest(line=line, quoting=quoting):
                    self.assertEqual(parse_row(line), fields)

    def test_round_trip_and_stdlib_reader_agree(self):
        for fields in generated_rows():
            with self.subTest(fields=fields):
                line = format_row(fields)
                self.assertEqual(parse_row(line), fields)
                self.assertEqual(list(csv.reader([line], strict=True)), [fields])


if __name__ == "__main__":
    unittest.main()

