import itertools
import random
import unittest
from csvline import format_row, parse_row


class CsvRowTest(unittest.TestCase):
    @staticmethod
    def reference_format(fields):
        output = io.StringIO(newline="")
        csv.writer(output, lineterminator="\n").writerow(fields)
        return output.getvalue()[:-1]

    @staticmethod
    def generated_rows():
        # Exhaust every short field over ordinary text, both CSV metacharacters,
        # and whitespace, then exercise every ordered pair of those fields.
        fields = [""]
        for length in range(1, 4):
            fields.extend("".join(chars) for chars in itertools.product('a," ', repeat=length))
        yield []
        for field in fields:
            yield [field]
        for pair in itertools.product(fields, repeat=2):
            yield list(pair)

        # Longer rows/fields broaden coverage while keeping failures replayable.
        rng = random.Random(20261115)
        alphabet = 'ab09 ,"\t\\é雪🙂'
        for _ in range(600):
            yield [
                "".join(rng.choice(alphabet) for _ in range(rng.randrange(25)))
                for _ in range(rng.randrange(9))
            ]

    def test_format_plain(self):
        self.assertEqual(format_row(["a", "b"]), "a,b")

    def test_format_quotes_commas(self):
        self.assertEqual(format_row(["a,b", "c"]), '"a,b",c')

    def test_parse_plain(self):
        self.assertEqual(parse_row("a,b"), ["a", "b"])

    def test_parse_quoted(self):
        self.assertEqual(parse_row('"a,b",c'), ["a,b", "c"])

    def test_empty_rows_and_fields_are_distinct(self):
        cases = [
            ([], ""),
            ([""], '""'),
            (["", ""], ","),
            (["", "", ""], ",,"),
            (["", "a", ""], ",a,"),
            (["a", "", "b"], "a,,b"),
        ]
        for fields, line in cases:
            with self.subTest(fields=fields, line=line):
                self.assertEqual(format_row(fields), line)
                self.assertEqual(parse_row(line), fields)

    def test_quotes_are_doubled_and_literals_preserved(self):
        cases = [
            (['"'], '""""'),
            (['""'], '""""""'),
            (['a"b'], '"a""b"'),
            ([","], '","'),
            (['a,"b",c'], '"a,""b"",c"'),
            ([" a ", "\t", "é雪🙂", "\\"], " a ,\t,é雪🙂,\\"),
        ]
        for fields, line in cases:
            with self.subTest(fields=fields, line=line):
                self.assertEqual(format_row(fields), line)
                self.assertEqual(parse_row(line), fields)

    def test_parse_optional_quoting(self):
        # Valid CSV need not use the formatter's minimal quoting.
        cases = [
            ('"a","b"', ["a", "b"]),
            ('"",""', ["", ""]),
            ('"",a,""', ["", "a", ""]),
            ('" a ","é雪🙂"', [" a ", "é雪🙂"]),
            ('"a,b","c""d",', ["a,b", 'c"d', ""]),
        ]
        for line, fields in cases:
            with self.subTest(line=line):
                self.assertEqual(parse_row(line), fields)

    def test_format_matches_standard_library(self):
        for fields in self.generated_rows():
            with self.subTest(fields=fields):
                self.assertEqual(format_row(fields), self.reference_format(fields))

    def test_parse_matches_standard_library(self):
        for fields in self.generated_rows():
            line = self.reference_format(fields)
            with self.subTest(line=line):
                # Supplying one physical line also gives [] for the empty row.
                expected = next(csv.reader([line], strict=True))
                self.assertEqual(parse_row(line), expected)

    def test_generated_round_trips(self):
        for fields in self.generated_rows():
            with self.subTest(fields=fields):
                self.assertEqual(parse_row(format_row(fields)), fields)


