def reference_format(fields):
    """Use the standard library as an independent encoding oracle."""
    stream = io.StringIO(newline="")
    csv.writer(stream, lineterminator="\r\n").writerow(fields)
    return stream.getvalue()[:-2]  # Remove exactly the record terminator.


def generated_rows():
    # Exhaustive short rows exercise boundary interactions, not just each token
    # in isolation (e.g. empty fields beside escaped quotes and delimiters).
    tokens = ("", "a", " ", "\t", ",", '"', '",', '""', "a,b", 'a"b', "é雪🙂")
    for count in range(4):
        for fields in itertools.product(tokens, repeat=count):
            yield list(fields)

    # Seeded larger rows cover variable lengths, repeated delimiters/quotes,
    # whitespace and non-ASCII text without adding a package dependency.
    rng = random.Random(73021)
    alphabet = 'abcXYZ019 ,"\t:;\\é雪🙂'
    for _ in range(300):
        yield [
            "".join(rng.choice(alphabet) for _ in range(rng.randrange(97)))
            for _ in range(rng.randrange(25))
        ]
    yield [""] * 100
    yield ["x" * 4096, '"' * 1024, "," * 1024, ""]


class CsvRowTest(unittest.TestCase):
    def test_empty_rows_and_fields_are_distinct(self):
        for fields, line in (([], ""), ([""], '""'), (["", ""], ","),
                             (["", "a", ""], ",a,")):
            with self.subTest(fields=fields):
                self.assertEqual(format_row(fields), line)
                self.assertEqual(parse_row(line), fields)

    def test_format_and_parse_regressions(self):
        cases = (
            (["a", "b"], "a,b"),
            (["a,b", "c"], '"a,b",c'),
            (['"'], '""""'),
            (['a"b'], '"a""b"'),
            ([",", '"', ""], '\",\",\"\"\"\",'),
            ([" leading", "trailing ", "\t", "雪🙂"], " leading,trailing ,\t,雪🙂"),
        )
        for fields, line in cases:
            with self.subTest(fields=fields):
                self.assertEqual(format_row(fields), line)
                self.assertEqual(parse_row(line), fields)

    def test_format_matches_standard_library(self):
        for index, fields in enumerate(generated_rows()):
            with self.subTest(index=index, fields=fields):
                self.assertEqual(format_row(fields), reference_format(fields))

    def test_parse_independently_encoded_rows(self):
        # Build input without format_row so matching encoder/decoder bugs
        # cannot hide behind a successful round trip.
        for index, fields in enumerate(generated_rows()):
            with self.subTest(index=index, fields=fields):
                self.assertEqual(parse_row(reference_format(fields)), fields)

    def test_round_trip_preserves_every_field(self):
