"""Contract tests using only the Store's public operations and a dict oracle."""
import random
import unittest

from store import Store


class StoreBehaviorTest(unittest.TestCase):
    def assert_contents(self, store, expected, keys):
        for key in keys:
            with self.subTest(key=key):
                self.assertEqual(store.get(key), expected.get(key))

    def assert_survives_restart(self, store, expected, keys):
        self.assert_contents(store, expected, keys)
        store.restart()
        self.assert_contents(store, expected, keys)
        store.restart()
        self.assert_contents(store, expected, keys)

    def test_empty_missing_and_repeated_delete(self):
        store = Store()
        self.assertIsNone(store.get("missing"))
        store.delete("missing")
        store.delete("missing")
        self.assert_survives_restart(store, {}, ["missing"])
        store.put("missing", 0)
        self.assert_survives_restart(store, {"missing": 0}, ["missing"])

    def test_overwrite_delete_and_reinsert_supported_keys_and_values(self):
        store = Store()
        keys = [None, "", 0, ("tuple", 7), frozenset({"frozen"})]
        expected = {}
        for value in [0, -12, 1.25, "", "text", float("inf")]:
            for key in keys:
                store.put(key, value)
                expected[key] = value
            self.assert_survives_restart(store, expected, keys)
        for key in keys:
            store.delete(key)
        self.assert_survives_restart(store, {}, keys)
        store.put_many((key, "again") for key in keys)
        self.assert_survives_restart(store, dict.fromkeys(keys, "again"), keys)

    def test_equal_keys_follow_dictionary_semantics(self):
        store = Store()
        store.put(1, "first")
        store.put(True, "last")
        self.assert_survives_restart(store, {1: "last"}, [1, True, 1.0])
        store.delete(1.0)
        self.assert_survives_restart(store, {}, [1, True, 1.0])

    def test_batch_is_ordered_and_accepts_one_shot_iterators(self):
        store = Store()
        store.put("existing", "old")
        store.put_many(iter([("existing", 2), ("new", ""), ("existing", 3.5)]))
        store.put_many(iter([]))
        self.assert_survives_restart(
            store, {"existing": 3.5, "new": ""}, ["existing", "new"]
        )

    def test_unhashable_single_keys_do_not_change_data_or_log(self):
        for operation in ["put", "delete"]:
            for key in [[], {}, {1}, ([],)]:
                with self.subTest(operation=operation, key=key):
                    store = Store()
                    store.put("kept", 9)
                    with self.assertRaises(TypeError):
                        if operation == "put":
                            store.put(key, "bad")
                        else:
                            store.delete(key)
                    self.assert_survives_restart(store, {"kept": 9}, ["kept"])
                    store.put("after", 10)
                    self.assert_survives_restart(
                        store, {"kept": 9, "after": 10}, ["kept", "after"]
                    )

    def test_invalid_batches_are_atomic_at_every_position_and_rollover(self):
        invalid_pairs = [("invalid", None), ("invalid", []),
                         ("invalid", {}), ("invalid", object()),
                         ("invalid", b"bytes"), ([], 1)]
        for initial_count in [0, 127, 639]:
            for invalid_pair in invalid_pairs:
                for position in [0, 1, 3]:
                    with self.subTest(initial_count=initial_count,
                                      invalid_pair=invalid_pair, position=position):
                        store = Store()
                        expected = {f"old-{i}": i for i in range(initial_count)}
                        store.put_many(expected.items())
                        store.put("existing", "original")
                        expected["existing"] = "original"
                        batch = [("existing", "changed"), ("new-1", 1), ("new-2", 2)]
                        batch.insert(position, invalid_pair)
                        with self.assertRaises(TypeError):
                            store.put_many(iter(batch))
                        keys = list(expected) + ["new-1", "new-2", "invalid"]
                        self.assert_survives_restart(store, expected, keys)

    def test_batch_iterator_failure_is_atomic(self):
        class InputFailure(Exception):
            pass

        def broken_items():
            yield "existing", "changed"
            yield "new", 1
            raise InputFailure("input ended unexpectedly")

        store = Store()
        store.put("existing", "original")
        with self.assertRaises(InputFailure):
            store.put_many(broken_items())
        self.assert_survives_restart(
            store, {"existing": "original"}, ["existing", "new"]
        )

    def test_rollover_and_repeated_compaction_preserve_latest_values(self):
        store = Store()
        expected = {}
        keys = [f"key-{i}" for i in range(173)]
        # More than 40 segments: old deletions, overwritten values, and keys
        # that appear in different generations must replay in chronological order.
        boundaries = {127, 128, 129, 511, 512, 513, 639, 640, 641}
        for count in range(1, 6001):
            key = keys[(count * 37) % len(keys)]
            if count % 5 in (0, 1):
                store.delete(key)
                expected.pop(key, None)
            else:
                store.put(key, count)
                expected[key] = count
            if count in boundaries or count % 128 == 0:
                self.assert_survives_restart(store, expected, keys)
        self.assert_survives_restart(store, expected, keys)
        for key in keys:
            store.delete(key)
        self.assert_survives_restart(store, {}, keys)

    def test_seeded_mixed_histories_match_dictionary(self):
        for seed in [0, 17, 982451653]:
            with self.subTest(seed=seed):
                rng = random.Random(seed)
                store = Store()
                expected = {}
                keys = [f"key-{i}" for i in range(211)]
                for step in range(3000):
                    key = rng.choice(keys)
                    operation = rng.randrange(10)
                    value = rng.choice([0, -7, 2.5, "", "value", step])
                    if operation < 4:
                        store.put(key, value)
                        expected[key] = value
                    elif operation < 6:
                        store.delete(key)
                        expected.pop(key, None)
                    elif operation < 8:
                        batch = [(rng.choice(keys), rng.choice([step, "", 1.25]))
                                 for _ in range(rng.randrange(12))]
                        store.put_many(iter(batch))
                        expected.update(batch)
                    elif operation == 8:
                        self.assertEqual(store.get(key), expected.get(key))
                    else:
                        self.assert_survives_restart(store, expected, keys)
                    if step % 100 == 0:
                        self.assert_contents(store, expected, keys)
                self.assert_survives_restart(store, expected, keys)

