"""Behavioral checks for the public store contract, including log maintenance."""

import random
import unittest

from store import Store


class CollisionKey:
    def __init__(self, value):
        self.value = value

    def __hash__(self):
        return 7

    def __eq__(self, other):
        return isinstance(other, CollisionKey) and self.value == other.value

    def __repr__(self):
        return f"CollisionKey({self.value!r})"


class StoreContractTest(unittest.TestCase):
    def assert_contents(self, store, expected, keys):
        for key in keys:
            self.assertEqual(store.get(key), expected.get(key), f"key={key!r}")

    def assert_survives_restart(self, store, expected, keys):
        self.assert_contents(store, expected, keys)
        for _ in range(2):
            store.restart()
            self.assert_contents(store, expected, keys)

    def test_empty_store_and_missing_delete_survive_restart(self):
        store = Store()
        store.delete("missing")
        self.assert_survives_restart(store, {}, ["missing", "other"])
        store.put("missing", 10)
        self.assert_survives_restart(store, {"missing": 10}, ["missing"])

    def test_overwrites_deletes_and_reinsertions_keep_latest_value(self):
        store = Store()
        for value in (0, "", 1.5, "latest"):
            store.put("key", value)
            self.assert_survives_restart(store, {"key": value}, ["key"])
        for _ in range(2):
            store.delete("key")
            self.assert_survives_restart(store, {}, ["key"])
        store.put("key", "reborn")
        self.assert_survives_restart(store, {"key": "reborn"}, ["key"])

    def test_hashable_keys_and_collisions_remain_distinct(self):
        keys = [None, "", 0, ("tuple", 2), frozenset({1, 2})]
        keys += [CollisionKey(i) for i in range(10)]
        store = Store()
        expected = {}
        for i, key in enumerate(keys):
            store.put(key, i)
            expected[key] = i
        # Look up by equal, independently constructed colliding keys as well.
        queries = keys + [CollisionKey(i) for i in range(11)]
        store.delete(CollisionKey(3))
        del expected[CollisionKey(3)]
        self.assert_survives_restart(store, expected, queries)

    def test_put_many_accepts_iterables_duplicates_and_all_supported_types(self):
        store = Store()
        items = [("int", -12), ("float", 1.25), ("str", ""),
                 ("duplicate", 1), ("duplicate", "last")]
        store.put_many(iter(items))
        store.put_many([])
        self.assert_survives_restart(store, dict(items), list(dict(items)))

    def test_put_and_delete_reject_unhashable_keys_without_changes(self):
        for operation in ("put", "delete"):
            for key in ([], {}, set()):
                with self.subTest(operation=operation, key=key):
                    store = Store()
                    store.put("existing", 7)
                    with self.assertRaises(TypeError):
                        if operation == "put":
                            store.put(key, 8)
                        else:
                            store.delete(key)
                    self.assert_survives_restart(store, {"existing": 7},
                                                 ["existing", "missing"])

    def test_invalid_batch_is_atomic_even_after_valid_overwrites(self):
        invalid_items = [("bad", None), ("bad", []), ("bad", {}),
                         ("bad", set()), ("bad", object()), ([], 3)]
        for invalid in invalid_items:
            for position in (0, 1, 3):
                with self.subTest(invalid=invalid, position=position):
                    store = Store()
                    store.put("existing", 7)
                    items = [("existing", 99), ("new", 2), ("existing", 100)]
                    items.insert(position, invalid)
                    with self.assertRaises(TypeError):
                        store.put_many(iter(items))
                    self.assert_survives_restart(store, {"existing": 7},
                                                 ["existing", "new", "bad"])

    def test_large_batch_keeps_every_key_through_repeated_merges(self):
        store = Store()
        expected = {f"key-{i}": i for i in range(2300)}
        store.put_many(expected.items())
        self.assert_survives_restart(store, expected, list(expected))
        # Continue writing after replay, so a successful rebuild alone is insufficient.
        for i in range(0, 2300, 3):
            store.delete(f"key-{i}")
            expected.pop(f"key-{i}")
        store.put_many((f"key-{i}", -i) for i in range(0, 2300, 5))
        expected.update((f"key-{i}", -i) for i in range(0, 2300, 5))
        self.assert_survives_restart(store, expected,
                                     [f"key-{i}" for i in range(2300)])

    def test_latest_updates_and_tombstones_across_log_boundaries(self):
        # Write counts surround segment rollover (128) and the first merge (640).
        checkpoints = {127, 128, 129, 255, 256, 257, 511, 512, 513,
                       639, 640, 641, 767, 768, 769, 1023, 1024, 1025,
                       2047, 2048, 2049, 4096}
        store = Store()
        expected = {}
        keys = [f"key-{i}" for i in range(311)]
        for i in range(4096):
            key = keys[i % len(keys)]
            if i % 5 in (1, 2):
                store.delete(key)
                expected.pop(key, None)
            else:
                store.put(key, i)
                expected[key] = i
            if i + 1 in checkpoints:
                with self.subTest(writes=i + 1):
                    self.assert_survives_restart(store, expected, keys)

    def test_rejected_batch_at_rollover_does_not_leave_replayable_prefix(self):
        for count in (127, 128, 639, 640, 1023):
            with self.subTest(prior_writes=count):
                store = Store()
                expected = {f"old-{i}": i for i in range(count)}
                store.put_many(expected.items())
                with self.assertRaises(TypeError):
                    store.put_many([("old-0", -1), ("new", 4), ("bad", None)])
                keys = list(expected) + ["new", "bad"]
                self.assert_survives_restart(store, expected, keys)
                store.put("new", 8)
                expected["new"] = 8
                self.assert_survives_restart(store, expected, keys)

    def test_seeded_mixed_histories_match_dictionary_model(self):
        for seed in (0, 1, 17, 2026):
            with self.subTest(seed=seed):
                rng = random.Random(seed)
                store = Store()
                expected = {}
                keys = [f"key-{i}" for i in range(180)]
                for step in range(2200):
                    action = rng.randrange(10)
                    key = rng.choice(keys)
                    if action < 4:
                        value = rng.choice([step, -step, step / 4, "", str(step)])
                        store.put(key, value)
                        expected[key] = value
                    elif action < 7:
                        store.delete(key)
                        expected.pop(key, None)
                    elif action < 9:
                        items = [(rng.choice(keys), f"{step}:{i}")
                                 for i in range(rng.randrange(12))]
                        store.put_many(iter(items))
                        expected.update(items)
                    else:
                        store.restart()
                    with self.subTest(step=step):
                        self.assert_contents(store, expected, keys)
                    if step % 113 == 0:
                        self.assert_survives_restart(store, expected, keys)
                self.assert_survives_restart(store, expected, keys)

