import csv
import io
import itertools
import unittest

from csvline import format_row, parse_row


# Small exhaustive alphabet deliberately includes delimiters, escapes and Unicode.
FIELDS = ["".join(chars) for length in range(3)
          for chars in itertools.product(('a', ',', '"', 'λ'), repeat=length)]


def rows():
    yield []
    for size in range(1, 4):
        yield from (list(row) for row in itertools.product(FIELDS, repeat=size))
    yield ['long plain field', ' spaced ', '🙂', '""",,,', '', 'tail']


def csv_encoded(row, quoting=csv.QUOTE_MINIMAL):
    output = io.StringIO(newline='')
    csv.writer(output, lineterminator='\n', quoting=quoting).writerow(row)
    return output.getvalue()[:-1]


class CsvRowTest(unittest.TestCase):
    def test_explicit_empty_and_escaping_cases(self):
        cases = [([], ''), ([''], '""'), (['', ''], ','),
                 (['a', ''], 'a,'), (['', 'a'], ',a'),
                 (['a"b'], '"a""b"'), ([',"'], '","""'),
                 (['λ', '🙂'], 'λ,🙂')]
        for fields, line in cases:
            with self.subTest(fields=fields):
                self.assertEqual(format_row(fields), line)
                self.assertEqual(parse_row(line), fields)

    def test_format_matches_csv_oracle(self):
        for fields in rows():
            with self.subTest(fields=fields):
                self.assertEqual(format_row(fields), csv_encoded(fields))

    def test_parse_csv_oracle_encodings(self):
        for fields in rows():
            for quoting in (csv.QUOTE_MINIMAL, csv.QUOTE_ALL):
                line = csv_encoded(fields, quoting)
                with self.subTest(fields=fields, quoting=quoting):
                    self.assertEqual(parse_row(line), fields)

    def test_round_trip(self):
        for fields in rows():
            with self.subTest(fields=fields):
                self.assertEqual(parse_row(format_row(fields)), fields)


if __name__ == '__main__':
    unittest.main()

import csv
import io
import itertools
import unittest

from csvline import format_row, parse_row


def reference_format(fields):
    output = io.StringIO(newline="")
    csv.writer(output, lineterminator="\n").writerow(fields)
    return output.getvalue()[:-1]


class CsvRowTest(unittest.TestCase):
    def test_format_examples(self):
        examples = [
            ([], ""),
            ([""], '""'),
            (["", ""], ","),
            (["a", "b"], "a,b"),
            (["a,b", "c"], '"a,b",c'),
            (['a"b', ""], '"a""b",'),
            (["", '"'], ',""""'),
        ]
        for fields, expected in examples:
            with self.subTest(fields=fields):
                self.assertEqual(format_row(fields), expected)
                self.assertEqual(parse_row(expected), fields)

    def test_generated_rows_match_csv_and_round_trip(self):
        alphabet = 'a ,"'
        fields = [""] + [
            "".join(chars)
            for length in (1, 2)
            for chars in itertools.product(alphabet, repeat=length)
        ]
        fields += ["unicode ☃", 'a,"b",c', '"""', "long plain field"]
        for count in range(4):
            for row in itertools.product(fields, repeat=count):
                row = list(row)
                with self.subTest(row=row):
                    expected = reference_format(row)
                    self.assertEqual(format_row(row), expected)
                    self.assertEqual(parse_row(expected), row)
                    self.assertEqual(parse_row(format_row(row)), row)

    def test_parse_valid_quoted_fields_even_when_quoting_is_optional(self):
        examples = {
            '"plain"': ["plain"],
            '"",plain,""': ["", "plain", ""],
            '"a""b","c,d"': ['a"b', "c,d"],
            '""""': ['"'],
        }
        for line, expected in examples.items():
            with self.subTest(line=line):
                self.assertEqual(parse_row(line), expected)


if __name__ == "__main__":
    unittest.main()
